<script lang="ts">
  let email = $state(""); let password = $state(""); let error = $state(""); let loading = $state(false);
  async function submit() { error = ""; loading = true; try { const response = await fetch("/api/platform/auth/login", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email, password }) }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error?.message ?? "Unable to sign in."); window.location.assign("/platform"); } catch (cause) { error = cause instanceof Error ? cause.message : "Unable to sign in."; } finally { loading = false; } }
</script>
<section class="card"><p class="eyebrow">Platform console</p><h1>Platform sign in</h1><form onsubmit={(event) => { event.preventDefault(); submit(); }}><label>Email<input type="email" bind:value={email} required disabled={loading} /></label><label>Password<input type="password" bind:value={password} required disabled={loading} /></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<button disabled={loading}>{loading ? "Signing in…" : "Sign in"}</button></form></section>
<style>
  .card { background: white; border: 1px solid #e1e7f0; border-radius: 1rem; margin: auto; max-width: 32rem; padding: 2rem; } .eyebrow { color: #168f76; font-size: .78rem; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; } form { display: grid; gap: 1rem; margin-top: 1.5rem; } label { display: grid; gap: .4rem; font-weight: 700; } input { border: 1px solid #cfd8e7; border-radius: .55rem; font: inherit; padding: .75rem; } button { background: #168f76; border: 0; border-radius: .55rem; color: white; font: inherit; font-weight: 750; padding: .8rem; } .error { background: #fff1f1; border-radius: .55rem; color: #a52929; padding: .75rem; }
</style>
